  "chapters": [
    {
      "chapter_id": 1,
      "sections": [
        {
          "section_id": 1,
          "title": "Death by Snacking",
          "intent": "Establish Artie's mundane life and his absurd death via vending machine.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Artie dies from electrocution and enters the Character Creation Void."
        },
        {
          "section_id": 2,
          "title": "The Grease-Fire Build",
          "intent": "Introduce Fizz and the UI glitch that locks Artie into the 1 HP / 100% Crit build.",
          "section_role": "conflict",
          "target_scene_count": 3,
          "end_condition": "Artie spawns in the tutorial forest with his glitched stats locked."
        },
        {
          "section_id": 3,
          "title": "The Participation Trophy",
          "intent": "Demonstrate the power of the crit build and introduce the cursed item mechanic.",
          "section_role": "conflict",
          "target_scene_count": 2,
          "end_condition": "Artie acquires the cursed Participation Trophy after vaporizing a slime."
        },
        {
          "section_id": 4,
          "title": "Oakhaven's Welcome",
          "intent": "Introduce the world's RNG obsession and the primary antagonist, Vane.",
          "section_role": "climax",
          "target_scene_count": 2,
          "end_condition": "Artie escapes a forced duel with Vane and enters Oakhaven proper."
        }
      ]
    },
    {
      "chapter_id": 2,
      "sections": [
        {
          "section_id": 1,
          "title": "The Coward's Wardrobe",
          "intent": "Artie seeks gear to survive his 1 HP fragility and exploits a quest loophole.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Artie steals the Cloak of the Cowardly Lion from a locked starter chest."
        },
        {
          "section_id": 2,
          "title": "Loot Pinata Theory",
          "intent": "Artie enters the crypts and discovers how his crits break the loot drop system.",
          "section_role": "conflict",
          "target_scene_count": 3,
          "end_condition": "Artie clears a room of skeletons, turning them into a mountain of loot."
        },
        {
          "section_id": 3,
          "title": "Summoning Trouble",
          "intent": "Vane's interference forces Artie to take a massive risk for XP.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "Artie activates the Boss Trigger left behind by Vane."
        }
      ]
    },
    {
      "chapter_id": 3,
      "sections": [
        {
          "section_id": 1,
          "title": "The Un-Crittable Golem",
          "intent": "Artie faces a boss that negates his primary advantage.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Fizz reveals the Bone Golem has a Crit-Resist aura."
        },
        {
          "section_id": 2,
          "title": "Critting the Environment",
          "intent": "Artie uses physics exploits to bypass the boss's mechanical defenses.",
          "section_role": "conflict",
          "target_scene_count": 4,
          "end_condition": "Artie defeats the Golem via a Cosmetic Crit and reaches Level 10."
        },
        {
          "section_id": 3,
          "title": "The First Glitch Mural",
          "intent": "Establish the deeper lore of the system and the threat of Vane's pursuit.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "Artie flees the crypts as Vane arrives to find the boss already dead."
        }
      ]
    },
    {
      "chapter_id": 4,
      "sections": [
        {
          "section_id": 1,
          "title": "The Temple of the D20",
          "intent": "Explore the capital's culture and Artie's search for a stat fix.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Artie learns that Stat-Wiping is a capital offense."
        },
        {
          "section_id": 2,
          "title": "The Lag-Switch Potion",
          "intent": "Artie interacts with the underground resistance and gains a temporary glitch tool.",
          "section_role": "conflict",
          "target_scene_count": 4,
          "end_condition": "Artie escapes a Sentinel raid by using the illegal Lag-Switch potion."
        },
        {
          "section_id": 3,
          "title": "High Stakes Entry",
          "intent": "Artie commits to the tournament to win the Shield of Infinite Health.",
          "section_role": "climax",
          "target_scene_count": 4,
          "end_condition": "Artie registers for the Grand Crit-Off and loses his entire gold reserve to fees."
        }
      ]
    },
    {
      "chapter_id": 5,
      "sections": [
        {
          "section_id": 1,
          "title": "Wardrobe Malfunction",
          "intent": "Artie wins his first matches using unconventional crit targets.",
          "section_role": "setup",
          "target_scene_count": 4,
          "end_condition": "Artie defeats a heavy tank by critting his belt buckle."
        },
        {
          "section_id": 2,
          "title": "Inverted Victory",
          "intent": "The System attempts to handicap Artie with random debuffs.",
          "section_role": "conflict",
          "target_scene_count": 4,
          "end_condition": "Artie wins the quarter-finals while suffering from an Inverted Controls debuff."
        },
        {
          "section_id": 3,
          "title": "The Glowing Trophy",
          "intent": "The cursed item begins to react to the high-density crit energy in the arena.",
          "section_role": "climax",
          "target_scene_count": 4,
          "end_condition": "Artie advances to the finals as the Participation Trophy begins to pulse with dark energy."
        }
      ]
    },
    {
      "chapter_id": 6,
      "sections": [
        {
          "section_id": 1,
          "title": "The Rigged Arena",
          "intent": "Vane uses his influence to strip Artie of his evasion advantages.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Vane activates a System Override scroll to disable Artie's dodge mechanics."
        },
        {
          "section_id": 2,
          "title": "Recursive Reflection",
          "intent": "Artie must find a way to hit Vane without killing himself on the Reflect armor.",
          "section_role": "conflict",
          "target_scene_count": 4,
          "end_condition": "Artie lands a meta-crit on the Reflect buff, causing the arena to pixelate."
        },
        {
          "section_id": 3,
          "title": "Deleting the Delete Button",
          "intent": "The System Administrator intervenes, and Artie must glitch his way out of existence.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "Artie and Fizz escape into Safe Mode after critting the Admin's UI."
        }
      ]
    },
    {
      "chapter_id": 7,
      "sections": [
        {
          "section_id": 1,
          "title": "The NaN Entity",
          "intent": "Artie explores his new status as a non-numerical glitch in the Null-Zone.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Artie confirms his NaN HP status by surviving a terminal fall."
        },
        {
          "section_id": 2,
          "title": "The Beta-Tester Faction",
          "intent": "Introduce the allies who will help Artie take down the Administrator.",
          "section_role": "conflict",
          "target_scene_count": 3,
          "end_condition": "Artie accepts the legendary quest to 'Delete the Admin'."
        },
        {
          "section_id": 3,
          "title": "Into the Glitch-Woods",
          "intent": "Set the stage for the next book and the escalation of the war against the System.",
          "section_role": "climax",
          "target_scene_count": 2,
          "end_condition": "Artie enters the portal to the Glitch-Woods, leaving the tutorial world behind."
        }
      ]
    }
  ]
}

